arguments.command:
cd /tmp/sv-f83f2130570840aca4a91d0080763f3d/symbols

# Get all dynamic symbols sorted, then find the range each address falls in
# This gives us: previous_symbol <= addr < next_symbol
for addr in 0x222098 0x222234 0x19bac0 0x19bc14; do
  echo -n "pc $addr -> "
  nm -D --defined-only libmonosgen-2.0.so 2>/dev/null | grep ' [TtWw] ' | sort | awk -v target="$addr" '
    BEGIN { gsub(/^0x/, "", target); best_name="??"; best_addr=0 }
    {
      addr_val = strtonum("0x" $1)
      tgt = strtonum("0x" target)
      if (addr_val <= tgt && addr_val > best_addr) {
        best_addr = addr_val
        best_name = $3
        best_offset = tgt - addr_val
      }
    }
    END { if (best_offset > 0) printf "%s+0x%x\n", best_name, best_offset; else printf "%s\n", best_name }
  '
done

echo ""
echo "--- Checking for closer symbols with objdump ---"
# Use objdump -T for more detail
objdump -T libmonosgen-2.0.so | grep -E "\.text" | awk '{print $1, $NF}' | sort | awk '
  BEGIN { 
    split("0x222098 0x222234 0x19bac0 0x19bc14", targets, " ")
  }
  {
    addr = strtonum("0x" $1)
    for (i in targets) {
      tgt = strtonum(targets[i])
      if (addr <= tgt && (!(i in best_addr) || addr > best_addr[i])) {
        best_addr[i] = addr
        best_name[i] = $2
        best_off[i] = tgt - addr
      }
    }
  }
  END {
    for (i in targets) {
      printf "%s -> %s+0x%x\n", targets[i], best_name[i], best_off[i]
    }
  }
'

