arguments.command:
cd /tmp/sv-f83f2130570840aca4a91d0080763f3d/symbols

# Let's get ALL symbols (including local if any remain) and look at the function map
# to get the most precise symbolication possible
nm -D --defined-only -S libmonosgen-2.0.so 2>/dev/null | grep ' [TtWw] ' | sort | awk '
{
  addr = strtonum("0x" $1)
  if (NF == 4) { size = strtonum("0x" $2); name = $4 }
  else { size = 0; name = $3 }
  targets["0x222098"] = strtonum("0x222098")
  targets["0x222234"] = strtonum("0x222234")  
  targets["0x19bac0"] = strtonum("0x19bac0")
  targets["0x19bc14"] = strtonum("0x19bc14")

  for (t in targets) {
    tgt = targets[t]
    if (addr <= tgt) {
      if (size > 0 && addr + size > tgt) {
        printf "EXACT: %s -> %s+0x%x (size=0x%x)\n", t, name, tgt-addr, size
      }
      if (!(t in best) || addr > best[t]) {
        best[t] = addr
        bestname[t] = name
        bestoff[t] = tgt - addr
      }
    }
  }
}
END {
  for (t in best) {
    if (!(t in printed)) printf "BEST: %s -> %s+0x%x\n", t, bestname[t], bestoff[t]
  }
}
'

